package com.bank.duplicate;

import java.util.*;
import java.util.logging.*;

public class DuplicateCharDemo {
    private static final Logger log = Logger.getLogger("Duplicate");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        DuplicateService service = new DuplicateService();
        log.info(() -> "programming → " + service.duplicateChars("programming"));
        log.info(() -> "abc         → " + service.duplicateChars("abc"));
    }
}

// ─── Would be in service/DuplicateService.java ───
class DuplicateService {
    List<Character> duplicateChars(String s) {
        Map<Character, Long> counts = s.chars()
            .mapToObj(c -> (char) c)
            .collect(java.util.stream.Collectors.groupingBy(
                c -> c, LinkedHashMap::new,                 // first-seen order
                java.util.stream.Collectors.counting()));
        return counts.entrySet().stream()
            .filter(e -> e.getValue() > 1L)                 // appears more than once
            .map(Map.Entry::getKey)
            .toList();
    }
}
